describe('Modal Backdrop Close Functionality', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');
  });

  it('should close modal when clicking on the backdrop', () => {
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should close modal when clicking outside modal content area', () => {
    cy.get('[data-testid="modal-backdrop"]').click('topLeft');
    cy.get('[data-testid="modal-container"]').should('not.be.visible');
  });

  it('should not close modal when clicking on modal content', () => {
    cy.get('[data-testid="modal-content"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');
  });

  it('should handle rapid backdrop clicks gracefully', () => {
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should close modal with backdrop click and reopen successfully', () => {
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });
    cy.get('[data-testid="modal-container"]').should('not.exist');
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');
  });

  it('should trigger close callback when backdrop is clicked', () => {
    cy.window().then((win) => {
      cy.spy(win, 'onModalClose');
    });
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });
    cy.window().its('onModalClose').should('have.been.called');
  });

  it('should maintain focus management after backdrop close', () => {
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });
    cy.get('[data-testid="open-modal-button"]').should('have.focus');
  });

  it('should handle backdrop click with keyboard modifier keys', () => {
    cy.get('[data-testid="modal-backdrop"]').click({ force: true, ctrlKey: true });
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should close modal when backdrop has pointer-events enabled', () => {
    cy.get('[data-testid="modal-backdrop"]')
      .should('have.css', 'pointer-events', 'auto')
      .click({ force: true });
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should handle backdrop close with animation completion', () => {
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });
    cy.get('[data-testid="modal-container"]', { timeout: 5000 }).should('not.exist');
  });
});
